export const PROTOCOL_FORM_PREFIX = 'protocol_';
export const protocolFormOf = (formKey: unknown): ProtocolForm | undefined =>
  typeof formKey === 'string' ? PROTOCOL_FORMS.find((f) => f.formKey === formKey) : undefined;

/** The form's title in a language: "שאלון לפני טיפול: אקנה". */
export const PROTOCOL_FORM_TITLE = { he: 'שאלון לפני טיפול', ar: 'استبيان قبل العلاج', en: 'Before your treatment' } as const;
export const protocolFormTitle = (f: ProtocolForm, lang: 'he' | 'ar' | 'en'): string => `${PROTOCOL_FORM_TITLE[lang]}: ${f.title[lang]}`;
